use super::*;
use crate::{DslValue,retirement::{RetireOwned,controlled::ControlledRetirement},retained_clone::RetainedCloneSource};
#[derive(crate::RetireOwned)]struct FlatRow{id:SealedShared<String>,name:SealedShared<String>,value:i64}
impl NativeFlatRecord<2,1> for FlatRow{
 const TEXT_FIELDS:[super::super::NativeRecordField;2]=[super::super::NativeRecordField{name:"id",ordinal:0},super::super::NativeRecordField{name:"name",ordinal:1}];
 const NUMBER_FIELDS:[super::super::NativeRecordField;1]=[super::super::NativeRecordField{name:"value",ordinal:2}];
 fn validation_demand(_: [&str;2],_:[Number;1])->RetirementDemand{fixed(size_of::<i64>())}
 fn validate_parts(_: [&str;2],numbers:[Number;1])->Result<(),ValueError>{numbers[0].as_i64().map(|_|()).ok_or_else(invalid)}
 fn from_parts([id,name]:[SealedShared<String>;2],numbers:[Number;1])->Self{Self{id,name,value:numbers[0].as_i64().unwrap()}}
}
fn funded(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn drain<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native original supports closure"));for _ in 0..10000{if owner.terminal_is_empty(){return;}let g=funded(owner.next_demand(4096).unwrap());assert!(owner.step(g).unwrap().progress().fits(g));}panic!("native flat fixture close stalled");}
fn source(value:DslValue)->RetainedCloneSource<DslValue>{let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),..funded(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).unwrap_or_else(|_|panic!("original input admission")).0}
#[test]
fn native_flat_record_receive_composes_original_fields_and_every_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();type Receiver=NativeFlatRecordReceiver<DslValue,FlatRow,2,1>;let mut finished=0;
 for cut in 0..128{let input=||DslValue::Object(law["canonical"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),if let Some(text)=pair[1].as_str(){DslValue::String(text.to_owned())}else{DslValue::Number(Number::Int(pair[1].as_i64().unwrap()))})).collect());let original=source(input());let foreign=source(input());let(mut receiver,_)=Receiver::begin(funded(Receiver::birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut turns=0;
  while turns<cut&&!receiver.output_ready(){let d=receiver.demands(original.borrow(),4096).unwrap();let g=funded(d);if turns>0{assert!(receiver.demands(foreign.borrow(),4096).is_err());}for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue};let(step,heap)=crate::value::observe_retirement_allocations(||control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,denied)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(original.borrow(),4096).unwrap(),d);}let(step,heap)=crate::value::observe_retirement_allocations(||control.with_construction_recipient(&mut construction,|control|receiver.advance(original.borrow(),control,g)).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;}
  if receiver.output_ready(){finished=turns;let g=funded(receiver.take_demand().unwrap());let(row,p)=receiver.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(row.id.as_str(),law["expected"]["id"].as_str().unwrap());assert_eq!(row.name.as_str(),law["expected"]["name"].as_str().unwrap());assert_eq!(row.value,law["expected"]["value"].as_i64().unwrap());drain(row);}
  receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break;}let g=funded(receiver.close_demands(4096).unwrap());let(step,heap)=crate::value::observe_retirement_allocations(||receiver.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(receiver.terminal_is_empty());drain(original);drain(foreign);if finished>0&&cut>finished{break;}
 }assert!(finished>0);eprintln!("[DEBUG] shared native flat receiver {finished} turns, actual original fields and every prefix retired");
}
